package com.bank.approval;

import java.util.logging.Logger;

public class SubsequenceCounter {

    private static final Logger log = Logger.getLogger(SubsequenceCounter.class.getName());

    public long numDistinct(String s, String t) {
        int m = s.length(), n = t.length();
        long[][] dp = new long[m + 1][n + 1];          // long to avoid overflow
        for (int i = 0; i <= m; i++) dp[i][0] = 1;     // empty target: one way (take nothing)
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                if (s.charAt(i - 1) == t.charAt(j - 1)) {
                    dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j]; // use it + skip it
                } else {
                    dp[i][j] = dp[i - 1][j];            // can only skip s char
                }
            }
        }
        long result = dp[m][n];
        log.info(() -> "Distinct subsequence count = " + result);
        return result;
    }
}
