package com.bank.approval;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class DistinctSubseqDemo {

    private static final Logger log = Logger.getLogger(DistinctSubseqDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Approval Audit (Distinct Subsequences)");
        SubsequenceCounter counter = new SubsequenceCounter();
        log.info("rabbbit contains rabbit → " + counter.numDistinct("rabbbit", "rabbit")); // 3
        log.info("babgbag contains bag → " + counter.numDistinct("babgbag", "bag"));         // 5
    }
}
